            new Quote { Id = "https://fr.wikiquote.org/wiki/Arthur_Rimbaud", Text = "- On n'est pas sérieux, quand on a dix-sept ans\nEt qu'on a des tilleuls verts sur la promenade.", Author = "Arthur Rimbaud" },
