            new Quote { Id = "https://fr.wikiquote.org/wiki/Arthur_Rimbaud", Text = "Je m'en allais, les poings dans mes poches crevées ;\nMon paletot aussi devenait idéal ;\nJ'allais sous le ciel, Muse ! et j'étais ton féal.", Author = "Arthur Rimbaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Arthur_Rimbaud", Text = "Comme je descendais des Fleuves impassibles \nJe ne me sentis plus guidé par les haleurs ;\nDes Peaux-Rouges criards les avaient pris pour cibles, \nLes ayant cloués nus aux poteaux de couleurs.", Author = "Arthur Rimbaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Arthur_Rimbaud", Text = "Glaciers, soleils d'argent, flots nacreux, cieux de braises,\nÉchouages hideux au fond des golfes bruns \nOù les serpents géants dévorés des punaises \nChoient, des arbres tordus avec de noirs parfums.", Author = "Arthur Rimbaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Arthur_Rimbaud", Text = "Mais, vrai, j'ai trop pleuré ! Les aubes sont navrantes.\nToute lune est atroce et tout soleil amer.", Author = "Arthur Rimbaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Arthur_Rimbaud", Text = "Jadis, si je me souviens bien, ma vie était un festin où s'ouvraient tous les cœurs, où tous les vins coulaient.\nUn soir, j'ai assis la Beauté sur mes genoux. - Et je l'ai trouvée amère. - Et je l'ai injuriée.", Author = "Arthur Rimbaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Arthur_Rimbaud", Text = "Le monde marche ! Pourquoi ne tournerait-il pas ?", Author = "Arthur Rimbaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Arthur_Rimbaud", Text = "Je suis esclave de mon baptême. Parents, vous avez fait mon malheur et vous avez fait le \nvôtre.", Author = "Arthur Rimbaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Arthur_Rimbaud", Text = "Je n'aime pas les femmes. L'amour est à réinventer.", Author = "Arthur Rimbaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Arthur_Rimbaud", Text = "J'écrivais des silences, des nuits, je notais l'inexprimable. Je fixais des vertiges.", Author = "Arthur Rimbaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Arthur_Rimbaud", Text = "La vieillerie poétique avait une bonne part dans mon alchimie du verbe.", Author = "Arthur Rimbaud" },
            new Quote { Id = "https://fr.wikiquote.org/wiki/Arthur_Rimbaud", Text = "La morale est la faiblesse de la cervelle. Acquise sans aucune reflexion, elle s'imprime en nous à nos dépens. Elle est un danger si elle n'est attuénuée par la pensée raisonnable.", Author = "Arthur Rimbaud" },
